try (AbstractPipeline pipe = redis.pipelined()) {
    pipe.set("idem:7f3a", "PENDING");
    Response<Long> replicas = pipe.waitReplicas("idem:7f3a", 1, 500);   // WAIT 1 500
    pipe.sync();
    if (replicas.get() < 1) {
        log.warn("idem:7f3a is on the primary only; a failover now could lose it");
    }
}

